-- Application resource database export; import once into an empty database.
SET NAMES utf8mb4;
CREATE DATABASE IF NOT EXISTS `source` CHARACTER SET utf8mb4;
USE `source`;

CREATE TABLE IF NOT EXISTS `资源库` (
  `id` char(20) NOT NULL,
  `name` varchar(255) DEFAULT NULL,
  `desc` varchar(255) DEFAULT NULL,
  `detailDesc` varchar(255) DEFAULT NULL,
  `uesDesc` varchar(255) DEFAULT NULL,
  `cateId` int(20) DEFAULT NULL,
  `size` varchar(20) DEFAULT NULL,
  `format` varchar(255) DEFAULT NULL,
  `download` varchar(255) DEFAULT NULL,
  `updateTime` datetime DEFAULT NULL,
  `tags` varchar(255) DEFAULT NULL,
  `downloadUrl` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

